/**
 * Stable numeric code of every failure, mirrored from the neutral `ErrorCode`.
 * Swift and Kotlin compare `TroupekitError.code` against these numbers.
 * The numbers are fixed forever and checked by `error_code_survives_conversion`.
 */

enum class ErrorCode(val value: kotlin.UInt) {
    
    CONFIG(1u),
    MISSING_KEY(2u),
    CATALOG(3u),
    PERSONA(4u),
    AGENT(5u),
    TOOL(6u),
    WORKFLOW(7u),
    GRAPH(8u),
    STORE(9u),
    CONTEXT(10u),
    FAILED(11u),
    PAUSED(12u),
    RETRIES(13u),
    CANCELLED(14u),
    HOST_CALLBACK(15u),
    INVALID_ARGUMENT(16u),
    UNSUPPORTED(17u),
    PANIC(18u),
    INTERNAL(99u);

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeErrorCode: FfiConverterRustBuffer<ErrorCode> {
    override fun read(buf: ByteBuffer) = try {
        ErrorCode.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ErrorCode) = 4UL

    override fun write(value: ErrorCode, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





