/**
 * @suppress
 */
public object FfiConverterTypeEventKind : FfiConverterRustBuffer<EventKind>{
    override fun read(buf: ByteBuffer): EventKind {
        return when(buf.getInt()) {
            1 -> EventKind.RunStarted(
                FfiConverterString.read(buf),
                )
            2 -> EventKind.StepStarted(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> EventKind.TextDelta(
                FfiConverterString.read(buf),
                )
            4 -> EventKind.ToolCallStarted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> EventKind.ToolCallFinished(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            6 -> EventKind.StepFinished(
                FfiConverterString.read(buf),
                FfiConverterTypeUsage.read(buf),
                )
            7 -> EventKind.RunPaused(
                FfiConverterTypePause.read(buf),
                )
            8 -> EventKind.RunFinished(
                FfiConverterTypeUsage.read(buf),
                )
            9 -> EventKind.RunFailed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EventKind): ULong = when(value) {
        is EventKind.RunStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`workflow`)
            )
        }
        is EventKind.StepStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`step`)
                + FfiConverterOptionalString.allocationSize(value.`persona`)
            )
        }
        is EventKind.TextDelta -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is EventKind.ToolCallStarted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`callId`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is EventKind.ToolCallFinished -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`callId`)
                + FfiConverterBoolean.allocationSize(value.`isError`)
            )
        }
        is EventKind.StepFinished -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`step`)
                + FfiConverterTypeUsage.allocationSize(value.`usage`)
            )
        }
        is EventKind.RunPaused -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePause.allocationSize(value.`reason`)
            )
        }
        is EventKind.RunFinished -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeUsage.allocationSize(value.`usage`)
            )
        }
        is EventKind.RunFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`error`)
            )
        }
    }

    override fun write(value: EventKind, buf: ByteBuffer) {
        when(value) {
            is EventKind.RunStarted -> {
                buf.putInt(1)
                FfiConverterString.write(value.`workflow`, buf)
                Unit
            }
            is EventKind.StepStarted -> {
                buf.putInt(2)
                FfiConverterString.write(value.`step`, buf)
                FfiConverterOptionalString.write(value.`persona`, buf)
                Unit
            }
            is EventKind.TextDelta -> {
                buf.putInt(3)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is EventKind.ToolCallStarted -> {
                buf.putInt(4)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is EventKind.ToolCallFinished -> {
                buf.putInt(5)
                FfiConverterString.write(value.`callId`, buf)
                FfiConverterBoolean.write(value.`isError`, buf)
                Unit
            }
            is EventKind.StepFinished -> {
                buf.putInt(6)
                FfiConverterString.write(value.`step`, buf)
                FfiConverterTypeUsage.write(value.`usage`, buf)
                Unit
            }
            is EventKind.RunPaused -> {
                buf.putInt(7)
                FfiConverterTypePause.write(value.`reason`, buf)
                Unit
            }
            is EventKind.RunFinished -> {
                buf.putInt(8)
                FfiConverterTypeUsage.write(value.`usage`, buf)
                Unit
            }
            is EventKind.RunFailed -> {
                buf.putInt(9)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







